const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';

const text = [
  'Với Google Sheets, Mia có thể tạo bảng tính, đọc dữ liệu, đọc vùng dữ liệu, thêm dòng, cập nhật ô, cập nhật vùng, tìm sheet và xoá sheet.',
  '',
  'Anh Minh thử nhanh như sau:',
  '- tạo sheet Chi tiêu',
  '- đọc sheet Chi tiêu',
  '- đọc vùng A1:C10 của sheet Chi tiêu',
  '- thêm dòng vào sheet Chi tiêu: cafe,30000,ăn uống',
  '- cập nhật sheet Chi tiêu ô B2 thành 35000',
  '- cập nhật vùng A1:B3 của sheet Chi tiêu',
  '- tìm sheet Chi tiêu',
  '- xóa sheet Chi tiêu',
].join('\n');

return [{ json: { chatId, text } }];
